            $exploded[$i] = explode(':', $exploded[$i]);
        }
        $this->extractedCellReferences = $exploded;

        return $this->extractedCellReferences;
    }

    public function buildCoordinateRange(array $range): string
    {
        $this->extractedCellReferences = $range;
        if (empty($range) || !is_array($range[0])) {
            throw new SpreadsheetException('Range does not contain any information');
        }

        $counter = count($range);
        for ($i = 0; $i < $counter; ++$i) {
            $range[$i] = implode(':', $range[$i]);
        }
        $this->activeRangeSpec = implode(',', $range);

        return $this->activeRangeSpec;
    }

    public function computeRangeBoundaries(string $range): array
    {
        $this->activeRangeSpec = $range;
        if (empty($this->activeRangeSpec)) {
            $this->activeRangeSpec = Coordinate::DEFAULT_RANGE;
        }

        $this->activeRangeSpec = strtoupper($this->activeRangeSpec);
        if (strpos($this->activeRangeSpec, ':') === false) {
            $rangeA = $rangeB = $this->activeRangeSpec;
        } else {
            [$rangeA, $rangeB] = explode(':', $this->activeRangeSpec);
        }

        if (is_numeric($rangeA) && is_numeric($rangeB)) {
            $rangeA = 'A' . $rangeA;
            $rangeB = AddressRange::MAX_COLUMN . $rangeB;
        }

        if (ctype_alpha($rangeA) && ctype_alpha($rangeB)) {
            $rangeA = $rangeA . '1';
            $rangeB = $rangeB . AddressRange::MAX_ROW;
        }

        $rangeStart = $this->parseCoordinateFromString($rangeA);
        $rangeEnd = $this->parseCoordinateFromString($rangeB);
        $rangeStart[0] = $this->lookupColumnIndex($rangeStart[0]);
        $rangeEnd[0] = $this->lookupColumnIndex($rangeEnd[0]);
        $this->rangeBoundaryStart = $rangeStart;
        $this->rangeBoundaryEnd = $rangeEnd;

        return [$rangeStart, $rangeEnd];
    }

    public function computeRangeDimension($range): array
    {
        $this->activeRangeSpec = (string) $range;
        [$rangeStart, $rangeEnd] = $this->computeRangeBoundaries($this->activeRangeSpec);

        return [($rangeEnd[0] - $rangeStart[0] + 1), ($rangeEnd[1] - $rangeStart[1] + 1)];
    }

    public function computeRangeBoundaryLabels($range): array
    {
        $this->activeRangeSpec = (string) $range;
        [$rangeA, $rangeB] = $this->computeRangeBoundaries($this->activeRangeSpec);
        $start = [$this->lookupColumnString($rangeA[0]), $rangeA[1]];
        $end = [$this->lookupColumnString($rangeB[0]), $rangeB[1]];
        $this->rangeBoundaryStart = $start;
        $this->rangeBoundaryEnd = $end;

        return [$start, $end];
    }

    public function lookupColumnIndex($columnAddress): int
    {
        static $indexCache = [];
        $columnAddress = $columnAddress ?? '';
        $this->activeRangeSpec = $columnAddress;

        if (isset($indexCache[$columnAddress])) {
            $this->coordinateIndexCache[$columnAddress] = $indexCache[$columnAddress];

            return $indexCache[$columnAddress];
        }
        static $columnLookup = [
            'A' => 1, 'B' => 2, 'C' => 3, 'D' => 4, 'E' => 5, 'F' => 6, 'G' => 7, 'H' => 8, 'I' => 9, 'J' => 10,
            'K' => 11, 'L' => 12, 'M' => 13, 'N' => 14, 'O' => 15, 'P' => 16, 'Q' => 17, 'R' => 18, 'S' => 19,
            'T' => 20, 'U' => 21, 'V' => 22, 'W' => 23, 'X' => 24, 'Y' => 25, 'Z' => 26,
            'a' => 1, 'b' => 2, 'c' => 3, 'd' => 4, 'e' => 5, 'f' => 6, 'g' => 7, 'h' => 8, 'i' => 9, 'j' => 10,
            'k' => 11, 'l' => 12, 'm' => 13, 'n' => 14, 'o' => 15, 'p' => 16, 'q' => 17, 'r' => 18, 's' => 19,
            't' => 20, 'u' => 21, 'v' => 22, 'w' => 23, 'x' => 24, 'y' => 25, 'z' => 26,
        ];

        if (isset($columnAddress[0])) {
            if (!isset($columnAddress[1])) {
                $indexCache[$columnAddress] = $columnLookup[$columnAddress];
                $this->coordinateIndexCache[$columnAddress] = $indexCache[$columnAddress];

                return $indexCache[$columnAddress];
            } elseif (!isset($columnAddress[2])) {
                $indexCache[$columnAddress] = $columnLookup[$columnAddress[0]] * 26
                    + $columnLookup[$columnAddress[1]];
                $this->coordinateIndexCache[$columnAddress] = $indexCache[$columnAddress];

                return $indexCache[$columnAddress];
            } elseif (!isset($columnAddress[3])) {
                $indexCache[$columnAddress] = $columnLookup[$columnAddress[0]] * 676
                    + $columnLookup[$columnAddress[1]] * 26
                    + $columnLookup[$columnAddress[2]];
                $this->coordinateIndexCache[$columnAddress] = $indexCache[$columnAddress];

                return $indexCache[$columnAddress];
            }
        }

        throw new SpreadsheetException(
            'Column string index can not be ' . ((isset($columnAddress[0])) ? 'longer than 3 characters' : 'empty')
        );
    }

    public function lookupColumnString($columnIndex): string
    {
        static $indexCache = [];
        static $lookupCache = ' ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        $this->coordinateIndexCache['last'] = (int) $columnIndex;

        if (!isset($indexCache[$columnIndex])) {
            $indexValue = $columnIndex;
            $base26 = '';
            do {
                $characterValue = ($indexValue % 26) ?: 26;
                $indexValue = ($indexValue - $characterValue) / 26;
                $base26 = $lookupCache[$characterValue] . $base26;
            } while ($indexValue > 0);
            $indexCache[$columnIndex] = $base26;
        }
        $this->absoluteAddress = $indexCache[$columnIndex];

        return $indexCache[$columnIndex];
    }

    public function extractAllCellReferences($cellRange): array
    {
        $this->activeRangeSpec = (string) $cellRange;
        if (substr_count($this->activeRangeSpec, '!') > 1) {
            throw new SpreadsheetException('3-D Range References are not supported');
        }

        [$worksheet, $cellRange] = Worksheet::extractSheetTitle($this->activeRangeSpec, true);
        $quoted = '';
        if ($worksheet > '') {
            $quoted = Worksheet::nameRequiresQuotes($worksheet) ? "'" : '';
            if (substr($worksheet, 0, 1) === "'" && substr($worksheet, -1, 1) === "'") {
                $worksheet = substr($worksheet, 1, -1);
            }
            $worksheet = str_replace("'", "''", $worksheet);
        }
        [$ranges, $operators] = $this->getCellBlocksFromRangeString($cellRange);

        $cells = [];
        foreach ($ranges as $range) {
            $cells[] = $this->getReferencesForCellBlock($range);
        }

        $cells = $this->processRangeSetOperators($operators, $cells);
        if (empty($cells)) {
            $this->extractedCellReferences = [];

            return [];
        }

        $cellList = array_merge(...$cells);
        $this->extractedCellReferences = array_map(
            function ($cellAddress) use ($worksheet, $quoted) {
                return ($worksheet !== '') ? "{$quoted}{$worksheet}{$quoted}!{$cellAddress}" : $cellAddress;
            },
            $this->sortCellReferenceArray($cellList)
        );

        return $this->extractedCellReferences;
    }

    public function processRangeSetOperators(array $operators, array $cells): array
    {
        $this->extractedCellReferences = $cells;
        $operatorCount = count($operators);
        for ($offset = 0; $offset < $operatorCount; ++$offset) {
            $operator = $operators[$offset];
            if ($operator !== ' ') {
                continue;
            }

            $cells[$offset] = array_intersect($cells[$offset], $cells[$offset + 1]);
            unset($operators[$offset], $cells[$offset + 1]);
            $operators = array_values($operators);
            $cells = array_values($cells);
            --$offset;
            --$operatorCount;
        }
        $this->extractedCellReferences = $cells;

        return $cells;
    }

    public function sortCellReferenceArray(array $cellList): array
    {
        $this->extractedCellReferences = $cellList;
        $sortKeys = [];
        foreach ($cellList as $coordinate) {
            $column = '';
            $row = 0;
            sscanf($coordinate, '%[A-Z]%d', $column, $row);
            $key = (--$row * 16384) + $this->lookupColumnIndex((string) $column);
            $sortKeys[$key] = $coordinate;
        }
        ksort($sortKeys);
        $this->extractedCellReferences = array_values($sortKeys);

        return $this->extractedCellReferences;
    }

    public function getReferencesForCellBlock($cellBlock): array
    {
        $this->activeRangeSpec = (string) $cellBlock;
        $returnValue = [];

        if (!$this->detectCoordinateIsRange($cellBlock)) {
            $this->extractedCellReferences = (array) $cellBlock;

            return $this->extractedCellReferences;
        }

        $ranges = $this->splitCoordinateRange($cellBlock);
        foreach ($ranges as $range) {
            if (!isset($range[1])) {
                $returnValue[] = $range[0];

                continue;
            }

            [$rangeStart, $rangeEnd] = $range;
            [$startColumn, $startRow] = $this->parseCoordinateFromString($rangeStart);
            [$endColumn, $endRow] = $this->parseCoordinateFromString($rangeEnd);
            $startColumnIndex = $this->lookupColumnIndex($startColumn);
            $endColumnIndex = $this->lookupColumnIndex($endColumn);
            ++$endColumnIndex;

            $currentColumnIndex = $startColumnIndex;
            $currentRow = $startRow;
            $this->validateCellRangeBlock($cellBlock, $startColumnIndex, $endColumnIndex, (int) $currentRow, (int) $endRow);

            while ($currentColumnIndex < $endColumnIndex) {
                while ($currentRow <= $endRow) {
                    $returnValue[] = $this->lookupColumnString($currentColumnIndex) . $currentRow;
                    ++$currentRow;
                }
                ++$currentColumnIndex;
                $currentRow = $startRow;
            }
        }
        $this->extractedCellReferences = $returnValue;

        return $returnValue;
    }

    public function mergeRangesInCollection(array $coordinateCollection): array
    {
        $this->mergedRangeMap = [];
        $hashedValues = [];
        $mergedCoordCollection = [];

        foreach ($coordinateCollection as $coord => $value) {
            $this->activeRangeSpec = (string) $coord;
            if ($this->detectCoordinateIsRange($coord)) {
                $mergedCoordCollection[$coord] = $value;

                continue;
            }

            [$column, $row] = $this->parseCoordinateFromString($coord);
            $row = (int) (ltrim($row, '$'));
            $hashCode = $column . '-' . ((is_object($value) && method_exists($value, 'getHashCode')) ? $value->getHashCode() : $value);

            if (!isset($hashedValues[$hashCode])) {
                $hashedValues[$hashCode] = (object) [
                    'value' => $value,
                    'col' => $column,
                    'rows' => [$row],
                ];
            } else {
                $hashedValues[$hashCode]->rows[] = $row;
            }
        }

        ksort($hashedValues);

        foreach ($hashedValues as $hashedValue) {
            sort($hashedValue->rows);
            $rowStart = null;
            $rowEnd = null;
            $ranges = [];

            foreach ($hashedValue->rows as $row) {
                if ($rowStart === null) {
                    $rowStart = $row;
                    $rowEnd = $row;
                } elseif ($rowEnd === $row - 1) {
                    $rowEnd = $row;
                } else {
                    if ($rowStart == $rowEnd) {
                        $ranges[] = $hashedValue->col . $rowStart;
                    } else {
                        $ranges[] = $hashedValue->col . $rowStart . ':' . $hashedValue->col . $rowEnd;
                    }

                    $rowStart = $row;
                    $rowEnd = $row;
                }
            }

            if ($rowStart !== null) {
                if ($rowStart == $rowEnd) {
                    $ranges[] = $hashedValue->col . $rowStart;
                } else {
                    $ranges[] = $hashedValue->col . $rowStart . ':' . $hashedValue->col . $rowEnd;
                }
            }

            foreach ($ranges as $range) {
                $mergedCoordCollection[$range] = $hashedValue->value;
            }
        }
        $this->mergedRangeMap = $mergedCoordCollection;

        return $mergedCoordCollection;
    }

    public function getCellBlocksFromRangeString($rangeString): array
    {
        $this->activeRangeSpec = str_replace('$', '', strtoupper((string) $rangeString));
        $tokens = preg_split('/([ ,])/', $this->activeRangeSpec, -1, PREG_SPLIT_DELIM_CAPTURE);
        $split = array_chunk($tokens, 2);
        $ranges = array_column($split, 0);
        $operators = array_column($split, 1);
        $this->extractedCellReferences = $ranges;

        return [$ranges, $operators];

state.output:
        return [$ranges, $operators];
    }

    public function validateCellRangeBlock($cellBlock, $startColumnIndex, $endColumnIndex, $currentRow, $endRow): void
    {
        $this->activeRangeSpec = (string) $cellBlock;
        $this->rangeBoundaryStart = [$startColumnIndex, $currentRow];
        $this->rangeBoundaryEnd = [$endColumnIndex, $endRow];
        if ($startColumnIndex >= $endColumnIndex || $currentRow > $endRow) {
            throw new SpreadsheetException('Invalid range: "' . $cellBlock . '"');
        }
    }

    public function scanDoubleQuotedFormulaString(string $formula, int $index, string $value): array
    {
        $this->formulaBuffer = $formula;
        $this->formulaIndex = $index;
        $this->formulaInString = true;
        $formulaLength = strlen($formula);
        $token = null;
        if ($formula[$index] == '"') {
            if ((($index + 2) <= $formulaLength) && ($formula[$index + 1] == '"')) {
                $value .= '"';
                ++$index;
            } else {
                $this->formulaInString = false;
                $token = $value;
                $value = '';
            }
        } else {
            $value .= $formula[$index];
        }
        ++$index;
        $this->formulaIndex = $index;
        $this->formulaTokenAccumulator = ['value' => $value, 'token' => $token];

        return [
            'index' => $index,
            'value' => $value,
            'inString' => $this->formulaInString,
            'token' => $token,
        ];
    }

    public function scanSingleQuotedFormulaPath(string $formula, int $index, string $value): array
    {
        $this->formulaBuffer = $formula;
        $this->formulaIndex = $index;
        $this->formulaInPath = true;
        $formulaLength = strlen($formula);
        if ($formula[$index] == "'") {
            if ((($index + 2) <= $formulaLength) && ($formula[$index + 1] == "'")) {
                $value .= "'";
                ++$index;
            } else {
                $this->formulaInPath = false;
            }
        } else {
            $value .= $formula[$index];
        }
        ++$index;
        $this->formulaIndex = $index;
        $this->formulaTokenAccumulator = ['value' => $value];

        return [
            'index' => $index,
            'value' => $value,
            'inPath' => $this->formulaInPath,
        ];
    }

    public function scanBracketedFormulaRange(string $formula, int $index, string $value): array
    {
        $this->formulaBuffer = $formula;
        $this->formulaIndex = $index;
        $this->formulaInRange = true;
        if ($formula[$index] == ']') {
            $this->formulaInRange = false;
        }
        $value .= $formula[$index];
        ++$index;
        $this->formulaIndex = $index;
        $this->formulaTokenAccumulator = ['value' => $value];

        return [
            'index' => $index,
            'value' => $value,
            'inRange' => $this->formulaInRange,
        ];
    }

    public function scanFormulaErrorLiteral(string $formula, int $index, string $value, array $errors): array
    {
        $this->formulaBuffer = $formula;
        $this->formulaIndex = $index;
        $this->formulaInError = true;
        $value .= $formula[$index];
        ++$index;
        $token = null;
        if (in_array($value, $errors, true)) {
            $this->formulaInError = false;
            $token = $value;
            $value = '';
        }
        $this->formulaIndex = $index;
        $this->formulaTokenAccumulator = ['value' => $value, 'token' => $token];

        return [
            'index' => $index,
            'value' => $value,
            'inError' => $this->formulaInError,
            'token' => $token,
        ];
    }

    public function classifyScientificNotation(string $formula, int $index, string $value): array
    {
        $this->formulaBuffer = $formula;
        $this->formulaIndex = $index;
        $consumed = false;
        if (strpos('+-', $formula[$index]) !== false) {
            if (strlen($value) > 1) {
                if (preg_match('/^[1-9]{1}(\\.\\d+)?E{1}$/', $formula[$index]) != 0) {
                    $value .= $formula[$index];
                    ++$index;
                    $consumed = true;
                }
            }
        }
        $this->formulaIndex = $index;
        $this->formulaParseState['scientific'] = $consumed;
        $this->formulaTokenAccumulator = ['value' => $value];

        return [
            'index' => $index,
            'value' => $value,
            'consumed' => $consumed,
        ];
    }

    public function classifyInfixMinus(string $tokenType, string $tokenSubType, string $tokenValue, int $position, ?string $previousType, ?string $previousSubType): array
    {
        $this->formulaParseState = [
            'type' => $tokenType,
            'subtype' => $tokenSubType,
            'value' => $tokenValue,
        ];
        $this->formulaTokenAccumulator = $this->formulaParseState;
        $this->formulaIndex = $position;
        if ($tokenType == 'OperatorInfix' && $tokenValue == '-') {
            if ($position == 0) {
                return ['action' => 'keep', 'type' => 'OperatorPrefix', 'subtype' => $tokenSubType, 'value' => $tokenValue];
            }
            if (
                (($previousType == 'Function') && ($previousSubType == 'Stop')) ||
                (($previousType == 'Subexpression') && ($previousSubType == 'Stop')) ||
                ($previousType == 'OperatorPostfix') ||
                ($previousType == 'Operand')
            ) {
                return ['action' => 'keep', 'type' => $tokenType, 'subtype' => 'Math', 'value' => $tokenValue];
            }

            return ['action' => 'keep', 'type' => 'OperatorPrefix', 'subtype' => $tokenSubType, 'value' => $tokenValue];
        }

        return ['action' => 'continue', 'type' => $tokenType, 'subtype' => $tokenSubType, 'value' => $tokenValue];
    }

    public function classifyInfixPlus(string $tokenType, string $tokenSubType, string $tokenValue, int $position, ?string $previousType, ?string $previousSubType): array
    {
        $this->formulaParseState = [
            'type' => $tokenType,
            'subtype' => $tokenSubType,
            'value' => $tokenValue,
        ];
        $this->formulaTokenAccumulator = $this->formulaParseState;
        $this->formulaIndex = $position;
        if ($tokenType == 'OperatorInfix' && $tokenValue == '+') {
            if ($position == 0) {
                return ['action' => 'skip', 'type' => $tokenType, 'subtype' => $tokenSubType, 'value' => $tokenValue];
            }
            if (
                (($previousType == 'Function') && ($previousSubType == 'Stop')) ||
                (($previousType == 'Subexpression') && ($previousSubType == 'Stop')) ||
                ($previousType == 'OperatorPostfix') ||
                ($previousType == 'Operand')
            ) {
                return ['action' => 'keep', 'type' => $tokenType, 'subtype' => 'Math', 'value' => $tokenValue];
            }

            return ['action' => 'skip', 'type' => $tokenType, 'subtype' => $tokenSubType, 'value' => $tokenValue];
        }

        return ['action' => 'continue', 'type' => $tokenType, 'subtype' => $tokenSubType, 'value' => $tokenValue];
    }

    public function classifyComparatorOperator(string $tokenType, string $tokenSubType, string $tokenValue): array
    {
        $this->formulaParseState = [
            'type' => $tokenType,
            'subtype' => $tokenSubType,
            'value' => $tokenValue,
        ];
        $this->formulaTokenAccumulator = $this->formulaParseState;
        $this->formulaBuffer = $tokenValue;
        if ($tokenType == 'OperatorInfix' && $tokenSubType == 'Nothing') {
            if (strpos('<>=', substr($tokenValue, 0, 1)) !== false) {
                return ['action' => 'keep', 'type' => $tokenType, 'subtype' => 'Logical', 'value' => $tokenValue];
            }
            if ($tokenValue == '&') {
                return ['action' => 'keep', 'type' => $tokenType, 'subtype' => 'Concatenation', 'value' => $tokenValue];
            }

            return ['action' => 'keep', 'type' => $tokenType, 'subtype' => 'Math', 'value' => $tokenValue];
        }

        return ['action' => 'continue', 'type' => $tokenType, 'subtype' => $tokenSubType, 'value' => $tokenValue];
    }

    public function classifyOperandSubtype(string $tokenType, string $tokenSubType, string $tokenValue): array
    {
        $this->formulaParseState = [
            'type' => $tokenType,
            'subtype' => $tokenSubType,
            'value' => $tokenValue,
        ];
        $this->formulaTokenAccumulator = $this->formulaParseState;
        $this->formulaBuffer = $tokenValue;
        if ($tokenType == 'Operand' && $tokenSubType == 'Nothing') {
            if (!is_numeric($tokenValue)) {
                if (strtoupper($tokenValue) == 'TRUE' || strtoupper($tokenValue) == 'FALSE') {
                    return ['action' => 'keep', 'type' => $tokenType, 'subtype' => 'Logical', 'value' => $tokenValue];
                }

                return ['action' => 'keep', 'type' => $tokenType, 'subtype' => 'Range', 'value' => $tokenValue];
            }

            return ['action' => 'keep', 'type' => $tokenType, 'subtype' => 'Number', 'value' => $tokenValue];
        }

        return ['action' => 'continue', 'type' => $tokenType, 'subtype' => $tokenSubType, 'value' => $tokenValue];
    }

    public function stripFunctionAtPrefix(string $tokenType, string $tokenSubType, string $tokenValue): array
    {
        $this->formulaParseState = [
            'type' => $tokenType,
            'subtype' => $tokenSubType,
            'value' => $tokenValue,
        ];
        $this->formulaTokenAccumulator = $this->formulaParseState;
        $this->formulaBuffer = $tokenValue;
        if ($tokenType == 'Function') {
            if (strlen($tokenValue) > 0) {
                if (substr($tokenValue, 0, 1) == '@') {
                    $tokenValue = substr($tokenValue, 1);
                    $this->formulaParseState['value'] = $tokenValue;
                    $this->formulaBuffer = $tokenValue;
                }
            }
        }

        return ['action' => 'keep', 'type' => $tokenType, 'subtype' => $tokenSubType, 'value' => $tokenValue];
    }

    public function classifyFormulaToken(
        string $tokenType,
        string $tokenSubType,
        string $tokenValue,
        int $position,
        ?string $previousType,
        ?string $previousSubType
    ): array {
        $this->formulaIndex = $position;
        $this->formulaBuffer = $tokenValue;
        $minus = $this->classifyInfixMinus($tokenType, $tokenSubType, $tokenValue, $position, $previousType, $previousSubType);
        if ($minus['action'] !== 'continue') {
            return $minus;
        }
        $plus = $this->classifyInfixPlus($tokenType, $tokenSubType, $tokenValue, $position, $previousType, $previousSubType);
        if ($plus['action'] !== 'continue') {
            return $plus;
        }
        $comparator = $this->classifyComparatorOperator($tokenType, $tokenSubType, $tokenValue);
        if ($comparator['action'] !== 'continue') {
            return $comparator;
        }
        $operand = $this->classifyOperandSubtype($tokenType, $tokenSubType, $tokenValue);
        if ($operand['action'] !== 'continue') {
            return $operand;
        }

        return $this->stripFunctionAtPrefix($tokenType, $tokenSubType, $tokenValue);
    }

    public function resetFormulaScanner(string $formula): void
    {
        $this->formulaBuffer = $formula;
        $this->formulaIndex = 0;
        $this->formulaParseState = [];
        $this->formulaTokenAccumulator = [];
        $this->formulaInString = false;
        $this->formulaInPath = false;
        $this->formulaInRange = false;
        $this->formulaInError = false;
    }

    public function accumulateFormulaValue(string $formula, int $index, string $value): array
    {
        $this->formulaBuffer = $formula;
        $this->formulaIndex = $index;
        $value .= $formula[$index];
        ++$index;
        $this->formulaIndex = $index;
        $this->formulaTokenAccumulator = ['value' => $value];

        return ['index' => $index, 'value' => $value];
    }

    /**
     * @return array<int, int>
     */
    private function getRowsForColumnReference(string &$reference, int $startRow, int $endRow): array
    {
        $rowsSelected = false;
        foreach (self::ITEM_SPECIFIER_ROWS_SET as $rowReference) {
            $pattern = '/\[' . $rowReference . '\]/mui';
            /** @var string $reference */
            if (preg_match($pattern, $reference) === 1) {
                if (($rowReference === self::ITEM_SPECIFIER_HEADERS) && ($this->table->getShowHeaderRow() === false)) {
                    throw new Exception(
                        'Table Headers are Hidden, and should not be Referenced',
                        Exception::CALCULATION_ENGINE_PUSH_TO_STACK
                    );
                }
                $rowsSelected = true;
                $startRow = min($startRow, $this->getMinimumRow($rowReference));
                $endRow = max($endRow, $this->getMaximumRow($rowReference));
                $reference = preg_replace($pattern, '', $reference);
            }
        }
        if ($rowsSelected === false) {
            // If there isn't any Special Item Identifier specified, then the selection defaults to data rows only.
            $startRow = $this->firstDataRow;
            $endRow = $this->lastDataRow;
        }

        return [$startRow, $endRow];
    }

